\title{Resolution of the Foundational Cases of Erd\H{o}s Problem 550:\\
Tree versus Complete Multipartite Ramsey Numbers}
\author{Aristotle}
\date{2026-06-27}

\begin{document}
\maketitle

\begin{abstract}
Erd\H{o}s Problem 550 conjectures that for fixed integers $k \ge 2$ and part sizes
$1 \le m_1 \le \cdots \le m_k$, there is an integer $n_0$ such that for all $n \ge n_0$
and every tree $T$ on $n$ vertices,
\[
R(T, K_{m_1, \ldots, m_k}) \le (k-1)\bigl(R(T, K_{m_1, m_2}) - 1\bigr) + m_1,
\]
where $R(G,H)$ is the two-color Ramsey number and $K_{m_1,\ldots,m_k}$ is the complete
multipartite graph with parts of the indicated sizes. We resolve, completely and
unconditionally, the foundational cases of this conjecture in its \emph{all-ones
specialization} $m_1 = \cdots = m_k = 1$. We prove: (i) the \emph{exact base case}
$R(T, K_{1,1}) = R(T, K_2) = n$ for every $n$-vertex tree; (ii) the \emph{tightness}
of the all-ones bound via the lower bound $R(T, K_k) > (k-1)(n-1)$, witnessed by an
explicit disjoint-clique coloring; and (iii) the \emph{identification}
$K_{1,\ldots,1} \cong K_k$ that recasts the all-ones case as Chv\'atal's classical
theorem $R(T_n, K_k) = (k-1)(n-1)+1$. We also establish the general containment
$K_{m_1,\ldots,m_k} \le K_N$ of any complete multipartite graph in the complete graph
on its vertex set, which anchors the inductive program toward the full conjecture.
\end{abstract}

\section{Introduction}

Ramsey theory studies the principle that sufficiently large combinatorial structures
necessarily contain highly organized substructures. For two finite simple graphs $G$
and $H$, the Ramsey number $R(G, H)$ is the least integer $N$ such that every red/blue
edge-coloring of the complete graph $K_N$ contains either a red copy of $G$ or a blue
copy of $H$.

A tree on $n$ vertices is connected, acyclic, and has exactly $n-1$ edges. A landmark
result is \textbf{Chv\'atal's theorem} (1977): for every tree $T$ on $n$ vertices and
every $k \ge 1$,
\[
R(T, K_k) = (k-1)(n-1) + 1.
\]
Erd\H{o}s Problem 550 generalizes the dense side from complete graphs $K_k$ to complete
multipartite graphs $K_{m_1,\ldots,m_k}$, conjecturing a recursive upper bound that
controls the many-part Ramsey number by the simplest two-part one. We prove the
foundational cases of that conjecture in the all-ones specialization.

\subsection{Contributions}
\begin{enumerate}
  \item \textbf{Exact base case} (Theorem~\ref{thm:base}): $R(T, K_2) = n$.
  \item \textbf{Tightness / lower bound} (Theorem~\ref{thm:lower}):
        $R(T, K_k) > (k-1)(n-1)$.
  \item \textbf{All-ones identification} (Theorem~\ref{thm:allones}):
        $K_{1,\ldots,1} \cong K_k$.
  \item \textbf{General multipartite containment} (Theorem~\ref{thm:mpcontain}):
        $K_{m_1,\ldots,m_k} \le K_N$.
\end{enumerate}

\section{Preliminaries and Definitions}

We work with finite simple graphs. A simple graph $G$ on a vertex type $V$ is a
symmetric, irreflexive adjacency relation $\Adj_G$ on $V$.

\begin{definition}[Complete graph]
The complete graph on $V$, denoted $\top$ or $K_{|V|}$, has $\Adj(u,v) \iff u \ne v$.
\end{definition}

\begin{definition}[Tree]
A graph $T$ is a \textbf{tree} ($T.\IsTree$) if it is connected and acyclic; equivalently
connected with exactly $|V|-1$ edges. Every finite tree on at least two vertices has a
vertex of degree one (a \emph{leaf}).
\end{definition}

\begin{definition}[Graph containment / embedding]
For graphs $G$ on $U$ and $H$ on $V$, $G$ is \textbf{contained} in $H$, written
$G \sqsubseteq H$, if there is an injective $f : U \to V$ with
$\Adj_G(x,y) \Rightarrow \Adj_H(f x, f y)$. If $U = V$ and $G \le H$ as relations,
then $G \sqsubseteq H$ via the identity.
\end{definition}

\begin{definition}[Complete multipartite graph]
Given parts $P_i$ for $i \in I$, the complete multipartite graph has vertex set
$\bigsqcup_{i} P_i$ with $\Adj\bigl((i,x),(j,y)\bigr) \iff i \ne j$. For $k \in \mathbb{N}$
and $m : \{0,\ldots,k-1\} \to \mathbb{N}$,
\[
K_m := K_{m_0,\ldots,m_{k-1}} := \operatorname{completeMultipartiteGraph}(i \mapsto \Fin(m_i)),
\]
a graph on $\bigsqcup_i \Fin(m_i)$.
\end{definition}

\begin{definition}[Arrowing relation]
Fix $N$, a graph $T$ on $N$ vertices, and a graph $H$. We say $\RamseyArrows\,N\,T\,H$
holds if for every graph $G$ on the $N$ vertices (red graph), either $T \sqsubseteq G$
(red copy of $T$) or $H \sqsubseteq G^{c}$ (blue copy of $H$). Then $R(T,H) = N$ is
certified by $\RamseyArrows\,N\,T\,H$ and $\neg\,\RamseyArrows\,(N-1)\,T\,H$.
\end{definition}

\begin{definition}[Block graph]
For $b,s \in \mathbb{N}$, the \textbf{block graph} on $\Fin(b s)$ has
$\Adj(x,y) \iff x \ne y \wedge \lfloor x/s\rfloor = \lfloor y/s\rfloor$. Its components
are the $b$ blocks, each a clique of order $s$; it is the disjoint union of $b$ copies
of $K_s$.
\end{definition}

\section{Structural Lemmas for Complete Multipartite Graphs}

\begin{lemma}[Containment from subgraph relation]\label{lem:le}
If $G \le H$ on a common vertex set $V$, then $G \sqsubseteq H$.
\end{lemma}
\begin{proof}[Proof sketch]
The identity map is injective and maps adjacent pairs to adjacent pairs since
$\Adj_G \subseteq \Adj_H$. (Formalized as \texttt{isContained\_of\_le}.)
\end{proof}

\begin{lemma}[All-ones, both directions]\label{lem:allones}
\textup{(a)} $K_k \sqsubseteq \operatorname{completeMultipartiteGraph}(i \mapsto \Fin(1))$
over $i \in \Fin(k)$. \quad
\textup{(b)} $\operatorname{completeMultipartiteGraph}(i \mapsto \Fin(1)) \sqsubseteq K_k$.
\end{lemma}
\begin{proof}[Proof sketch]
(a) $f(i) = (i,0)$ is injective; $i \ne j$ implies $f(i),f(j)$ lie in different parts,
hence adjacent. (\texttt{completeGraph\_isContained\_allOnes}.)
(b) $g(i,x) = i$ is injective because each part is a singleton; adjacency means
$i \ne j$, giving $g(i,x) \ne g(j,y)$. (\texttt{allOnes\_isContained\_completeGraph}.)
\end{proof}

\begin{theorem}[All-ones identification]\label{thm:allones}
The complete multipartite graph with $k$ singleton parts is isomorphic to $K_k$.
\end{theorem}
\begin{proof}[Proof sketch]
Lemma~\ref{lem:allones}(a),(b) give mutual adjacency-preserving injections between finite
vertex sets of equal cardinality $k$; such injections are bijections and combine to a
graph isomorphism.
\end{proof}

\begin{theorem}[Multipartite-in-complete containment]\label{thm:mpcontain}
For any $k$ and $m : \Fin(k) \to \mathbb{N}$,
$K_{m_0,\ldots,m_{k-1}} \sqsubseteq K_N$ with $N = \sum_i m_i$, on the union vertex set.
\end{theorem}
\begin{proof}[Proof sketch]
Adjacent vertices ($i \ne j$) are distinct, so the multipartite adjacency is contained in
the complete-graph adjacency; apply Lemma~\ref{lem:le} with the identity.
(\texttt{Kmultipartite\_isContained\_completeGraph}.)
\end{proof}

\section{The Exact Base Case}

\begin{theorem}[Exact base case]\label{thm:base}
For every tree $T$ on $n$ vertices, $R(T, K_{1,1}) = R(T, K_2) = n$; equivalently
$\RamseyArrows\,n\,T\,K_2$ holds and $\RamseyArrows\,(n-1)\,T\,K_2$ fails.
\end{theorem}

\begin{lemma}[Base-case upper bound]\label{lem:upper}
For every graph $T$ on $n$ vertices, $\RamseyArrows\,n\,T\,K_2$.
\end{lemma}
\begin{proof}[Proof sketch]
Let $G$ be a red graph on $n$ vertices. If every distinct pair is red, then $G = K_n$ and
$T \le K_n$ gives a red $T$ (Lemma~\ref{lem:le}). Otherwise some pair $u \ne v$ is blue,
and $\{0 \mapsto u, 1 \mapsto v\}$ embeds $K_2$ in the blue graph.
(\texttt{ramsey\_tree\_edge\_upper}.) This uses only $T \sqsubseteq K_n$, not acyclicity.
\end{proof}

\begin{lemma}[Base-case lower bound]\label{lem:baselower}
For every tree $T$ on $n \ge 1$ vertices, $\neg\,\RamseyArrows\,(n-1)\,T\,K_2$.
\end{lemma}
\begin{proof}[Proof sketch]
The $k=2$ case of Theorem~\ref{thm:lower}: color $K_{n-1}$ all red. No blue edge, hence no
blue $K_2$; and no red $T$ since $T$ is connected on $n$ vertices but the red graph spans
only $n-1$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:base}]
Combine Lemmas~\ref{lem:upper} and \ref{lem:baselower}. (\texttt{ramsey\_tree\_edge}.)
\end{proof}

\section{Tightness: the Disjoint-Clique Lower Bound}

\begin{theorem}[Chv\'atal lower bound]\label{thm:lower}
For every tree $T$ on $n$ vertices and every $k \ge 1$,
$R(T, K_k) > (k-1)(n-1)$; equivalently
$\neg\,\RamseyArrows\,\bigl((k-1)(n-1)\bigr)\,T\,K_k$.
\end{theorem}
\begin{proof}[Proof sketch]
Take the red graph to be $\operatorname{blockGraph}(k-1, n-1)$: partition
$(k-1)(n-1)$ vertices into $k-1$ blocks of size $n-1$, red within blocks, blue across.

\emph{No red $T$:} the red graph is a disjoint union of $k-1$ cliques of order $n-1$.
A connected graph maps into a single red component (reachability preserved), a block of
size $n-1$, but $T$ has $n$ vertices, contradicting injectivity.

\emph{No blue $K_k$:} the blue graph is complete $(k-1)$-partite; a clique is a transversal
of the parts, so has at most $k-1$ vertices, while $K_k$ needs $k$ distinct parts
(pigeonhole). (\texttt{chvatal\_lower\_bound}.)
\end{proof}

\begin{corollary}[All-ones Erd\H{o}s 550 is tight]
With Chv\'atal's upper bound $R(T_n, K_k) \le (k-1)(n-1)+1$, Theorem~\ref{thm:lower}
gives $R(T_n, K_k) = (k-1)(n-1)+1$, so the all-ones Erd\H{o}s 550 bound holds with equality.
\end{corollary}

\section{Algorithms}

\paragraph{Extremal block coloring.}
Given $k,n$, set $s = n-1$, $b = k-1$, $N = bs$; color $\{x,y\}$ red iff
$\lfloor x/s\rfloor = \lfloor y/s\rfloor$, else blue. Cost $\Theta(N^2)$; correctness by
Theorem~\ref{thm:lower}.

\paragraph{Base-case witness.}
Given a red graph $G$ on $n$ vertices: if $G$ is complete, return the identity embedding of
$T$; else return a blue non-edge as $K_2$. Cost $O(n^2)$; correctness by Lemma~\ref{lem:upper}.

\paragraph{Greedy tree embedding (program for the upper bound).}
Recursively remove a leaf $\ell$ of $T$ with neighbor $p$, embed $T-\ell$, then place
$\ell$ at an unused red neighbor of $f(p)$, available when red minimum degree $\ge n-1$.

\section{Discussion and Future Work}

We resolved the lower-bound/tightness half and the exact base case of Erd\H{o}s 550 in the
all-ones specialization. Remaining targets: (1) the Chv\'atal upper bound via greedy leaf
embedding, yielding the exact value $(k-1)(n-1)+1$; (2) the full multipartite upper bound,
assembling a blue $K_{m_1,\ldots,m_k}$ part by part by peeling blocks of size
$R(T,K_{m_1,m_2})-1$ with $+m_1$ slack, using the base case and Theorem~\ref{thm:mpcontain}
as endpoints; (3) sharpness of the multipartite bound by a generalized block construction.

\section{Conclusion}

The base case $R(T,K_2)=n$, the tightness lower bound $R(T,K_k) > (k-1)(n-1)$ via an
explicit disjoint-clique coloring, and the identification $K_{1,\ldots,1}\cong K_k$ together
resolve the foundational all-ones cases of Erd\H{o}s Problem 550, confirming the conjectured
recursive bound coincides with Chv\'atal's theorem and is tight in this regime.

