function BLOCK_COLORING(k, n):
    s <- n - 1            # block size
    b <- k - 1            # number of blocks
    N <- b * s
    for each pair {x, y}, 0 <= x < y < N:
        if floor(x / s) == floor(y / s):
            color(x, y) <- RED      # same block -> clique edge
        else:
            color(x, y) <- BLUE     # different blocks
    return (N, color)

function CONTAINS_COPY(n_small, E_small, n_big, adj_big):
    for each injection f : {0..n_small-1} -> {0..n_big-1}:
        ok <- true
        for each edge (x, y) in E_small:
            if not adj_big(f(x), f(y)):
                ok <- false; break
        if ok: return true
    return false
